const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Geometry for Lake Tuz, Turkey
    const aoi = ee.Geometry.Rectangle([32.9, 38.45, 33.8, 39.1]);
    const date1988 = ee.Filter.date('1988-08-01', '1988-08-31');
    const date2016 = ee.Filter.date('2016-08-01', '2016-08-31');

    // 2. Data Acquisition & Processing Functions
    const maskL5Clouds = function(image) {
        const qa = image.select('QA_PIXEL');
        // Bits 3 and 5 are cloud shadow and cloud, respectively.
        const cloudShadowBitMask = (1 << 3);
        const cloudsBitMask = (1 << 5);
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                        .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    };

    const maskL8Clouds = function(image) {
        const qa = image.select('QA_PIXEL');
        // Bits 3 and 5 are cloud shadow and cloud, respectively.
        const cloudShadowBitMask = (1 << 3);
        const cloudsBitMask = (1 << 5);
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                        .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    };

    const calculateWaterArea = async (image, scale, source) => {
        // Calculate NDWI: (Green - NIR) / (Green + NIR)
        // Landsat 5: Green=SR_B2, NIR=SR_B4
        // Landsat 8: Green=SR_B3, NIR=SR_B5
        const green = image.select(source === 'L5' ? 'SR_B2' : 'SR_B3');
        const nir = image.select(source === 'L5' ? 'SR_B4' : 'SR_B5');

        // Scale factor for Landsat Surface Reflectance is 0.0000275, add offset of -0.2
        const ndwi = green.multiply(0.0000275).add(-0.2)
                        .subtract(nir.multiply(0.0000275).add(-0.2))
                        .divide(green.multiply(0.0000275).add(-0.2)
                        .add(nir.multiply(0.0000275).add(-0.2)))
                        .rename('ndwi');

        const waterMask = ndwi.gt(0.2);

        const areaImage = waterMask.multiply(ee.Image.pixelArea());
        const stats = areaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        });

        const area = stats.get('ndwi');

        // C2 Check: Check valid pixel count for the NDWI band within the geometry
        const count = ndwi.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        }).get('ndwi').getInfo();

        if (count === 0) {
            return { area: null, pixels: 0 };
        }

        return { area: area.getInfo(), pixels: count };
    };

    // 3. Image Selection
    // For 1988
    const col1988 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
                        .filter(aoi)
                        .filter(date1988)
                        .map(maskL5Clouds);

    // For 2016
    const col2016 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                        .filter(aoi)
                        .filter(date2016)
                        .map(maskL8Clouds);

    const size1988 = col1988.size().getInfo();
    const size2016 = col2016.size().getInfo();

    if (size1988 === 0 || size2016 === 0) {
        console.log(`Image count 1988: ${size1988}`);
        console.log(`Image count 2016: ${size2016}`);
        console.log("C1: Empty Collection");
        return;
    }

    const image1988 = col1988.qualityMosaic('NDVI');
    const image2016 = col2016.qualityMosaic('NDVI');

    // 4. Calculation
    const result1988 = await calculateWaterArea(image1988, 30, 'L5');
    const result2016 = await calculateWaterArea(image2016, 30, 'L8');

    const area1988 = result1988.area;
    const area2016 = result2016.area;

    // 5. Validation & Final Answer
    if (result1988.pixels === 0 || result2016.pixels === 0) {
        console.log(`Valid pixels in 1988: ${result1988.pixels}`);
        console.log(`Valid pixels in 2016: ${result2016.pixels}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    if (area1988 === null || area2016 === null) {
        console.log(`Area 1988: ${area1988}`);
        console.log(`Area 2016: ${area2016}`);
        console.log("C3: Calculation Failure");
        return;
    }

    const area1988_km2 = area1988 / 1e6;
    const area2016_km2 = area2016 / 1e6;

    console.log(`1988 water area (km2): ${area1988_km2.toFixed(2)}`);
    console.log(`2016 water area (km2): ${area2016_km2.toFixed(2)}`);

    if (area2016_km2 < area1988_km2) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(e);
    console.log("D");
  }
}

initEE();
